using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ElectrostaticFieldEffect", menuName = "Data/Battle/Effects/Austra/ElectrostaticField Effect")]
public class ElectrostaticFieldEffect : Effect
{
	[Header("Electrostatic Field")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		GameObject gameObject = currentActiveUnits.IsUnitWithElectrostaticField(effectOwner);
		if ((bool)gameObject && gameObject != effectOwner)
		{
			gameObject.GetComponent<UnitEffects>().RemoveEffect(this);
		}
	}
}
